<span pulumi-lang-nodejs="`regionalCertificateArn " pulumi-lang-dotnet="`RegionalCertificateArn " pulumi-lang-go="`regionalCertificateArn " pulumi-lang-python="`regional_certificate_arn " pulumi-lang-yaml="`regionalCertificateArn " pulumi-lang-java="`regionalCertificateArn " pulumi-lang-hcl="`regional_certificate_arn ">`regionalCertificateArn </span>= aws_acm_certificate_validation.cert.certificate_arn`.

## Example Usage

### Edge Optimized (ACM Certificate)

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

const example = new aws.apigateway.DomainName("example", {
    certificateArn: exampleAwsAcmCertificateValidation.certificateArn,
    domainName: "api.example.com",
});
// Example DNS record using Route53.
// Route53 is not specifically required; any DNS host can be used.
const exampleRecord = new aws.route53.Record("example", {
    aliases: [{
        evaluateTargetHealth: true,
        name: example.cloudfrontDomainName,
        zoneId: example.cloudfrontZoneId,
    }],
