### Customer Managed Encryption

Omitting <span pulumi-lang-nodejs="`encryptionConfiguration`" pulumi-lang-dotnet="`EncryptionConfiguration`" pulumi-lang-go="`encryptionConfiguration`" pulumi-lang-python="`encryption_configuration`" pulumi-lang-yaml="`encryptionConfiguration`" pulumi-lang-java="`encryptionConfiguration`" pulumi-lang-hcl="`encryption_configuration`">`encryptionConfiguration`</span> leaves the space encrypted with an AWS owned key. To use a customer managed key, the key policy must grant the `cloudwatch.amazonaws.com` service principal permission to use it, otherwise `CreateSpace` fails with `AccessDeniedException`.

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

const current = aws.getCallerIdentity({});
const example = new aws.kms.Key("example", {
    description: "CloudWatch Omni Space encryption",
    policy: JSON.stringify({
        Version: "2012-10-17",
        Statement: [
            {
                Sid: "EnableIAMUserPermissions",
                Effect: "Allow",
                Principal: {
                    AWS: current.then(current => `arn:aws:iam::${current.accountId}:root`),
                },
                Action: "kms:*",
                Resource: "*",
            },
            {
                Sid: "AllowCloudWatchOmni",
                Effect: "Allow",
                Principal: {
                    Service: "cloudwatch.amazonaws.com",
                },
                Action: [
                    "kms:Decrypt",
                    "kms:DescribeKey",
                    "kms:Encrypt",
                    "kms:GenerateDataKey*",
                    "kms:ReEncrypt*",
                ],
                Resource: "*",
            },
        ],
    }),
});
const exampleSpace = new aws.cloudwatchomni.Space("example", {
    encryptionConfiguration: {
        encryptionStrategy: "CUSTOMER_MANAGED",
        kmsKeyArn: example.arn,
    },
    name: "example",
    domainId: exampleAwsCloudwatchomniDomain.domainId,
    dataAccessRoleArn: exampleAwsIamRole.arn,
});
