aws:codedeploy/deploymentConfig:Deployme.description:
Provides a CodeDeploy deployment config for an application

## Example Usage

### Server Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

const foo = new aws.codedeploy.DeploymentConfig("foo", {
    minimumHealthyHosts: {
        type: "HOST_COUNT",
        value: 2,
    },
    deploymentConfigName: "test-deployment-config",
});
const fooDeploymentGroup = new aws.codedeploy.DeploymentGroup("foo", {
    autoRollbackConfiguration: {
        enabled: true,
        events: ["DEPLOYMENT_FAILURE"],
    },
    alarmConfiguration: {
        alarms: ["my-alarm-name"],
        enabled: true,
    },
    ec2TagFilters: [{
        key: "filterkey",
        type: "KEY_AND_VALUE",
        value: "filtervalue",
    }],
    triggerConfigurations: [{
        triggerEvents: ["DeploymentFailure"],
        triggerName: "foo-trigger",
        triggerTargetArn: "foo-topic-arn",
    }],
    appName: fooApp.name,
    deploymentGroupName: "bar",
    serviceRoleArn: fooRole.arn,
    deploymentConfigName: foo.id,
});
```
