					"contentType": "json",
					"insecureSsl": true,
					"secret":      webhookSecret,
				},
			},
			Repository: pulumi.Any(repo.Name),
			Name:       "web",
			Events: pulumi.StringArray{
				pulumi.String("push"),
			},
		})
		if err != nil {
			return err
		}
		return nil
	})
}
