### Replica Tagging

You can manage global table replicas' tags in various ways. This example shows using `replica.*.propagate_tags` for the first replica and the <span pulumi-lang-nodejs="`aws.dynamodb.Tag`" pulumi-lang-dotnet="`aws.dynamodb.Tag`" pulumi-lang-go="`dynamodb.Tag`" pulumi-lang-python="`dynamodb.Tag`" pulumi-lang-yaml="`aws.dynamodb.Tag`" pulumi-lang-java="`aws.dynamodb.Tag`" pulumi-lang-hcl="`aws_dynamodb_tag`">`aws.dynamodb.Tag`</span> resource for the other.

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import * as std from "@pulumi/std";

const current = aws.getRegion({});
const alternate = aws.getRegion({});
const third = aws.getRegion({});
const example = new aws.dynamodb.Table("example", {
    attributes: [{
        name: "TestTableHashKey",
        type: "S",
    }],
    replicas: [
        {
            regionName: alternate.then(alternate => alternate.region),
        },
        {
            regionName: third.then(third => third.region),
            propagateTags: true,
        },
    ],
    billingMode: "PAY_PER_REQUEST",
    hashKey: "TestTableHashKey",
    name: "example-13281",
    streamEnabled: true,
    streamViewType: "NEW_AND_OLD_IMAGES",
    tags: {
        Architect: "Eleanor",
        Zone: "SW",
    },
});
const exampleTag = new aws.dynamodb.Tag("example", {
    resourceArn: std.replaceOutput({
        text: example.arn,
        search: current.then(current => current.region),
        replace: alternate.then(alternate => alternate.region),
    }).result,
    key: "Architect",
    value: "Gigi",
});
