    name: "example-network-connector-operator",
    assumeRolePolicy: JSON.stringify({
        Version: "2012-10-17",
        Statement: [{
            Action: "sts:AssumeRole",
            Effect: "Allow",
            Principal: {
                Service: "network-connectors.lambda.amazonaws.com",
            },
        }],
    }),
});
const example = new aws.lambda.CoreNetworkConnector("example", {
