### Emit events to EventBridge

For a bucket shared by multiple independent consumers — different teams, different Pulumi configurations, different applications — EventBridge is the recommended pattern. Each consumer subscribes to the bucket through its own <span pulumi-lang-nodejs="`aws.cloudwatch.EventRule`" pulumi-lang-dotnet="`aws.cloudwatch.EventRule`" pulumi-lang-go="`cloudwatch.EventRule`" pulumi-lang-python="`cloudwatch.EventRule`" pulumi-lang-yaml="`aws.cloudwatch.EventRule`" pulumi-lang-java="`aws.cloudwatch.EventRule`" pulumi-lang-hcl="`aws_cloudwatch_event_rule`">`aws.cloudwatch.EventRule`</span>, so they cannot overwrite one another the way notification configurations would.

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

const shared = new aws.s3.Bucket("shared", {bucket: "shared-bucket"});
const sharedBucketNotification = new aws.s3.BucketNotification("shared", {
    bucket: shared.id,
    eventbridge: true,
});
// Team A: process new uploads under uploads/
const teamA = new aws.cloudwatch.EventRule("team_a", {
    name: "team-a-uploads",
    eventPattern: pulumi.jsonStringify({
        source: ["aws.s3"],
        "detail-type": ["Object Created"],
        detail: {
            bucket: {
                name: [shared.bucket],
            },
            object: {
                key: [{
                    prefix: "uploads/",
                }],
            },
        },
    }),
});
const teamAEventTarget = new aws.cloudwatch.EventTarget("team_a", {
    rule: teamA.name,
    arn: teamAProcessor.arn,
});
// Team B: archive deletions under archive/, declared in a separate
// Pulumi configuration that knows nothing about Team A.
const teamB = new aws.cloudwatch.EventRule("team_b", {
    name: "team-b-deletions",
    eventPattern: pulumi.jsonStringify({
        source: ["aws.s3"],
        "detail-type": ["Object Deleted"],
        detail: {
            bucket: {
                name: [shared.bucket],
            },
            object: {
                key: [{
                    prefix: "archive/",
                }],
            },
        },
    }),
});
const teamBEventTarget = new aws.cloudwatch.EventTarget("team_b", {
    rule: teamB.name,
    arn: teamBArchive.arn,
});
