    specification: {
        computeResourceRequirements: {
            minMemoryRequiredInMb: 1024,
        },
        modelName: exampleAwsSagemakerModel.name,
    },
    runtimeConfig: {
        copyCount: 1,
    },
    name: "my-inference-component",
    endpointName: exampleAwsSagemakerEndpoint.name,
    variantName: "variant-1",
});
