                Netnum = range.Value,
            }).Apply(invoke => invoke.Result),
            AvailabilityZone = available.Names[range.Value],
        }));
    }
    var example1 = new List<Aws.Ec2.SecurityGroup>();
    for (var rangeIndex = 0; rangeIndex < 2; rangeIndex++)
    {
        var range = new { Value = rangeIndex };
