const current = aws.getCallerIdentity({});
const test = current.then(current => aws.licensemanager.getLicenseGrants({
    filters: [{
        name: "GranteePrincipalARN",
        values: [`arn:aws:iam::${current.accountId}:root`],
    }],
}));
```
