{
    var current = Aws.GetCallerIdentity.Invoke();

    var test = Aws.LicenseManager.GetLicenseGrants.Invoke(new()
    {
        Filters = new[]
        {
            new Aws.LicenseManager.Inputs.GetLicenseGrantsFilterInputArgs
            {
                Name = "GranteePrincipalARN",
                Values = new[]
                {
