    endpoints: [
        {
            id: "my_elb",
            type: "elastic-load-balancer",
            value: `elb-111111.${current.region}.elb.amazonaws.com`,
        },
        {
            id: "site_down_banner",
            type: "s3-website",
            region: current.region,
            value: "www.example.com",
        },
