            endpointReference: "site_down_banner",
        },
        id: "site_switch",
        type: "failover",
    }],
    recordType: "A",
    startRule: "site_switch",
}));
const exampleTrafficPolicy = new aws.route53.TrafficPolicy("example", {
    name: "example",
    comment: "example comment",
    document: example.then(example => example.json),
});
