import * as aws from "@pulumi/aws";

export = async () => {
    const shared = await aws.s3.getBucketNotification({
        bucket: "shared-bucket",
    });
    const s3ObjectCreated: aws.cloudwatch.EventRule[] = [];
    for (let range = 0; range < (shared.eventbridge ? 1 : 0); range++) {
